rm -rf /tmp/et0-relocation-test && mkdir -p /tmp/et0-relocation-test/data /tmp/et0-relocation-test/out && cp -a et0 /tmp/et0-relocation-test/ && cp config/stations.yaml /tmp/et0-relocation-test/stations.yaml && cp data/raw/PAL.csv data/raw/CDB.csv /tmp/et0-relocation-test/data/ && cd /tmp/et0-relocation-test && python -m et0.pipeline --stations stations.yaml --data data --out out/et0.csv && cd /app && python - <<'PY'
import csv
a = {(r['station_id'], r['date']): r['et0_mm_day'] for r in csv.DictReader(open('/tmp/et0-relocation-test/out/et0.csv'))}
